def _repository_root() -> Path:
    return Path(__file__).resolve().parents[2]


def _module_source_files() -> tuple[Path, ...]:
    root = _repository_root()
    module_root = root / "ares" / "modules"
    excluded = {
        "ares/modules/base.py",
        "ares/modules/descriptors.py",
        "ares/modules/params.py",
        "ares/modules/sdk.py",
    }
    result = []
    for path in module_root.rglob("*.py"):
        relative = path.relative_to(root).as_posix()
        if path.name == "__init__.py" or relative in excluded:
            continue
        result.append(path)
    return tuple(sorted(result))


def _literal_module_assignments() -> list[tuple[str, str, str, int]]:
    root = _repository_root()
    result = []
    for path in _module_source_files():
        tree = ast.parse(path.read_text(encoding="utf-8"))
        for node in tree.body:
            if not isinstance(node, ast.ClassDef):
                continue
            for item in node.body:
                targets = []
                value = None
                if isinstance(item, ast.Assign):
                    targets = item.targets
                    value = item.value
                elif isinstance(item, ast.AnnAssign):
                    targets = [item.target]
                    value = item.value
                if not any(
                    isinstance(target, ast.Name) and target.id == "MODULE_ID" for target in targets
                ):
                    continue
                if isinstance(value, ast.Constant) and isinstance(value.value, str) and value.value:
                    result.append(
                        (
                            value.value,
                            path.relative_to(root).as_posix(),
                            node.name,
                            node.lineno,
                        )
                    )
    return result


def _fixed_invalid(action) -> None:
    with pytest.raises(DescriptorReadinessError) as captured:
        action()
    assert captured.value.code is ReadinessCode.INVALID_DESCRIPTOR
    assert str(captured.value).startswith(ReadinessCode.INVALID_DESCRIPTOR.value)


def _actual_descriptor_record(module_id: str):
    descriptor = FIRST_PARTY_DESCRIPTORS[module_id]
    source_rows = {
        item_id: source_file
        for item_id, source_file, _class_name, _line in _literal_module_assignments()
    }
    return {
        "module_id": descriptor.module_id,
        "source_file": source_rows[module_id],
        "source_module": descriptor.source_module,
        "source_class": descriptor.source_class,
        "category": descriptor.category.value,
        "parameter_model_identity": descriptor.parameter_model_identity,
        "parameter_schema_digest": descriptor.parameter_schema_digest,
        "parameter_fields": tuple(
            {
                "name": item.name,
                "canonical_type": item.canonical_type.value,
                "required": item.required,
                "default_state": item.default_state.value,
                "public_default_digest": item.public_default_digest,
                "legacy_schema_secret": item.legacy_schema_secret,
                "sensitivity": item.sensitivity.value,
                "blocker_code": item.blocker_code.value if item.blocker_code else None,
                "nested_fields": (),
            }
            for item in descriptor.parameter_fields
        ),
        "declared_outputs": descriptor.declared_outputs,
        "opsec": descriptor.opsec.value,
        "minimum_role": descriptor.minimum_role.value,
        "explicit_attempt_approval": descriptor.explicit_attempt_approval,
        "required_capabilities": tuple(item.value for item in descriptor.required_capabilities),
        "capability_match": descriptor.capability_match.value,
        "destination_state": descriptor.destination_state.value,
        "destinations": tuple(
            {
                "state": item.state.value,
                "kind": item.kind.value,
                "source_path": item.source_path,
                "cardinality": item.cardinality.value,
                "scope": item.scope.value,
            }
            for item in descriptor.destinations
        ),
        "credential_policy": {
            "state": descriptor.credential_policy.state.value,
            "allowed_handle_kinds": tuple(
                item.value for item in descriptor.credential_policy.allowed_handle_kinds
            ),
            "ambient_dependencies": tuple(
                item.value for item in descriptor.credential_policy.ambient_dependencies
            ),
        },
        "external_effect": descriptor.external_effect.value,
        "idempotency": descriptor.idempotency.value,
        "retry_eligibility": descriptor.retry_eligibility.value,
        "cancellation_ownership": descriptor.cancellation_ownership.value,
        "compensation": descriptor.compensation.value,
        "timeout": {
            "seconds": descriptor.timeout.seconds,
            "source": descriptor.timeout.source.value,
            "settlement": descriptor.timeout.settlement.value,
        },
        "dry_run": {
            "state": descriptor.dry_run.state.value,
            "owner_module": descriptor.dry_run.owner_module,
            "owner_class": descriptor.dry_run.owner_class,
            "method_name": descriptor.dry_run.method_name,
            "guard_semantics": descriptor.dry_run.guard_semantics.value,
            "termination": descriptor.dry_run.termination.value,
            "provenance_digest": descriptor.dry_run.provenance_digest,
        },
        "result_contract": {
            "findings": descriptor.result_contract.findings.value,
            "credentials": descriptor.result_contract.credentials.value,
            "discovered_hosts": descriptor.result_contract.discovered_hosts.value,
            "loot_artifacts": descriptor.result_contract.loot_artifacts.value,
            "authoritative_evidence": (descriptor.result_contract.authoritative_evidence.value),
        },
        "descriptor_complete": descriptor.descriptor_complete,
        "future_gateway_eligible": descriptor.future_gateway_eligible,
        "blocker_codes": tuple(item.value for item in descriptor.blocker_codes),
        "legacy_requires": descriptor.legacy_requires,
        "legacy_capabilities": tuple(item.value for item in descriptor.legacy_capabilities),
        "legacy_dry_run_supported": descriptor.legacy_dry_run_supported,
        "legacy_timeout_override": descriptor.legacy_timeout_override,
        "semantic_digest": descriptor.semantic_digest,
    }


