def test_independent_collection_node_ids_are_exact() -> None:
    env = os.environ.copy()
    env["PYTHONDONTWRITEBYTECODE"] = "1"
    completed = subprocess.run(  # noqa: S603 - fixed interpreter and test path
        [
            sys.executable,
            "-m",
            "pytest",
            __file__,
            "--collect-only",
            "-qq",
            "-p",
            "no:cacheprovider",
        ],
        cwd=_repository_root(),
        env=env,
        capture_output=True,
        text=True,
        check=False,
        timeout=60,
    )
    actual = {
        line.strip().split("::", 1)[1]
        for line in completed.stdout.splitlines()
        if line.strip().startswith("tests/unit/test_module_descriptor_readiness.py::")
    }
    reduced = (completed.returncode == 0, actual == EXPECTED_COLLECTION_NODE_IDS)
    assert reduced == (True, True)


def test_independent_ast_census_matches_locked_inventory() -> None:
    source_files = _module_source_files()
    assignments = _literal_module_assignments()
    by_id: dict[str, list[tuple[str, str, int]]] = {}
    by_file: dict[str, set[str]] = {}
    for module_id, path, class_name, line in assignments:
        by_id.setdefault(module_id, []).append((path, class_name, line))
        by_file.setdefault(path, set()).add(module_id)

    assert len(source_files) == 60
    assert len(assignments) == 62
    assert len(by_id) == 62
    assert set(by_id) == set(EXPECTED_RECORDS)
    assert all(len(locations) == 1 for locations in by_id.values())
    assert len({module_id.casefold() for module_id in by_id}) == 62
    assert all(re.fullmatch(r"[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*", module_id) for module_id in by_id)
    actual_support = {
        path.relative_to(_repository_root()).as_posix()
        for path in source_files
        if path.relative_to(_repository_root()).as_posix() not in by_file
    }
    assert actual_support == EXPECTED_SUPPORT_ONLY_SOURCES
    actual_multi = {path: module_ids for path, module_ids in by_file.items() if len(module_ids) > 1}
    assert actual_multi == EXPECTED_MULTI_MODULE_SOURCES
    for module_id, locations in by_id.items():
        assert locations[0][0] == EXPECTED_RECORDS[module_id]["source_file"]


