_NO_DEFAULT = object()


def _construct_descriptor(
    source: ModuleDescriptor,
    **overrides: object,
) -> ModuleDescriptor:
    values = {
        item.name: getattr(source, item.name)
        for item in dataclass_fields(ModuleDescriptor)
        if item.init
    }
    values.update(overrides)
    return ModuleDescriptor(**values)


def _copy_parameter_field(
    source: ParameterFieldSpec,
    **overrides: object,
) -> ParameterFieldSpec:
    values = {
        item.name: getattr(source, item.name)
        for item in dataclass_fields(ParameterFieldSpec)
        if item.init
    }
    values["nested_fields"] = tuple(
        _copy_parameter_field(item) for item in source.nested_fields
    )
    values.update(overrides)
    return ParameterFieldSpec(**values)


def _secret_canary_model(default: object):
    field_default = ... if default is _NO_DEFAULT else default
    return create_model(
        "PassTheHashCanaryParams",
        __base__=runtime_params.PassTheHashParams,
        __module__="ares.modules.params",
        lm_hash=(
            str,
            Field(
                default=field_default,
                json_schema_extra={"secret": True},
            ),
        ),
    )


def _construct_secret_canary_descriptor(model: type) -> ModuleDescriptor:
    source = FIRST_PARTY_DESCRIPTORS["credential.pass_the_hash"]
    actual = model.model_fields["lm_hash"]
    state = _runtime_default_state(actual, Sensitivity.SECRET)
    blocker = (
        BlockerCode.SENSITIVE_NONEMPTY_DEFAULT
        if state is DefaultSemanticState.DEFAULT_NONEMPTY_BLOCKED
        else None
    )
    fields = tuple(
        (
            ParameterFieldSpec(
                name=item.name,
                canonical_type=_annotation_identity(actual.annotation),
                required=actual.is_required(),
                default_state=state,
                public_default_digest=None,
                legacy_schema_secret=bool((actual.json_schema_extra or {}).get("secret")),
                sensitivity=Sensitivity.SECRET,
                blocker_code=blocker,
                nested_fields=(),
            )
            if item.name == "lm_hash"
            else _copy_parameter_field(item)
        )
        for item in source.parameter_fields
    )
    return _construct_descriptor(
        source,
        parameter_model=model,
        parameter_model_identity=f"{model.__module__}.{model.__qualname__}",
        parameter_fields=fields,
    )


def _bind_secret_canary_descriptor(
    model: type,
    monkeypatch: pytest.MonkeyPatch,
) -> tuple[ModuleDescriptor, object]:
    descriptor = _construct_secret_canary_descriptor(model)
    descriptors = dict(FIRST_PARTY_DESCRIPTORS)
    descriptors[descriptor.module_id] = descriptor
    descriptor_tuple = tuple(
        descriptors[module_id] for module_id in sorted(descriptors)
    )
    params = dict(runtime_params.MODULE_PARAMS)
    params[descriptor.module_id] = model
    with monkeypatch.context() as scoped:
        scoped.setattr(descriptor_module, "FIRST_PARTY_DESCRIPTORS", descriptors)
        scoped.setattr(descriptor_module, "_FIRST_PARTY_DESCRIPTORS", descriptor_tuple)
        scoped.setattr(runtime_params, "MODULE_PARAMS", params)
        bound = validate_parameter_model_bindings()
        summary = readiness_summary()
    assert descriptor in bound
    return descriptor, summary


def _secret_observable_data(
    descriptor: ModuleDescriptor,
    summary: object,
) -> str:
    target = next(item for item in descriptor.parameter_fields if item.name == "lm_hash")
    observations = (
        _parameter_field_data(target),
        descriptor.parameter_schema_digest,
        repr(target),
        repr(descriptor),
        _semantic_data(descriptor),
        descriptor_semantic_digest(descriptor),
        repr(summary),
        str(DescriptorReadinessError(ReadinessCode.PARAMETER_CONTRACT_MISMATCH)),
        repr(DescriptorReadinessError(ReadinessCode.PARAMETER_CONTRACT_MISMATCH)),
    )
    return json.dumps(observations, sort_keys=True, default=str)


def test_nonempty_secret_canaries_never_enter_descriptor_or_digest_paths(
    capsys: pytest.CaptureFixture[str],
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    canary_a = "".join(chr(value) for value in (97, 108, 112, 104, 97, 45, 55, 49))
    canary_b = "".join(chr(value) for value in (98, 114, 97, 118, 111, 45, 56, 51))
    descriptor_a, summary_a = _bind_secret_canary_descriptor(
        _secret_canary_model(canary_a),
        monkeypatch,
    )
    descriptor_b, summary_b = _bind_secret_canary_descriptor(
        _secret_canary_model(canary_b),
        monkeypatch,
    )
    field_a = next(item for item in descriptor_a.parameter_fields if item.name == "lm_hash")
    field_b = next(item for item in descriptor_b.parameter_fields if item.name == "lm_hash")
    serialized = _secret_observable_data(descriptor_a, summary_a) + _secret_observable_data(
        descriptor_b,
        summary_b,
    )
    forbidden = (
        canary_a,
        canary_b,
        hashlib.sha256(canary_a.encode("utf-8")).hexdigest(),
        hashlib.sha256(canary_b.encode("utf-8")).hexdigest(),
    )
    captured = capsys.readouterr()
    reduced = (
        field_a.default_state is DefaultSemanticState.DEFAULT_NONEMPTY_BLOCKED,
        field_b.default_state is DefaultSemanticState.DEFAULT_NONEMPTY_BLOCKED,
        _parameter_field_data(field_a) == _parameter_field_data(field_b),
        _semantic_data(descriptor_a) == _semantic_data(descriptor_b),
        descriptor_semantic_digest(descriptor_a) == descriptor_semantic_digest(descriptor_b),
        all(value not in serialized for value in forbidden),
        all(value not in captured.out and value not in captured.err for value in forbidden),
    )
    assert reduced == (True, True, True, True, True, True, True)


def test_secret_default_state_transitions_change_semantic_digest(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    models = (
        _secret_canary_model(_NO_DEFAULT),
        _secret_canary_model(""),
        _secret_canary_model("".join(chr(value) for value in (99, 104, 97, 114, 108, 105, 101))),
    )
    descriptors = tuple(
        _bind_secret_canary_descriptor(model, monkeypatch)[0]
        for model in models
    )
    states = tuple(
        next(item for item in descriptor.parameter_fields if item.name == "lm_hash").default_state
        for descriptor in descriptors
    )
    digests = {descriptor_semantic_digest(descriptor) for descriptor in descriptors}
    assert states == (
        DefaultSemanticState.NO_DEFAULT,
        DefaultSemanticState.DEFAULT_EMPTY,
        DefaultSemanticState.DEFAULT_NONEMPTY_BLOCKED,
    )
    assert len(digests) == 3


def test_default_factory_is_classified_without_evaluation() -> None:
    called = False

    def factory():
        nonlocal called
        called = True
        raise AssertionError("ARES-5C1-DEFAULT-FACTORY")

    field_info = SimpleNamespace(
        is_required=lambda: False,
        default_factory=factory,
    )
    state = _runtime_default_state(field_info, Sensitivity.SECRET)
    spec = ParameterFieldSpec(
        name="secret_field",
        canonical_type=ParameterType.STRING,
        required=False,
        default_state=state,
        public_default_digest=None,
        legacy_schema_secret=False,
        sensitivity=Sensitivity.SECRET,
        blocker_code=BlockerCode.DEFAULT_FACTORY_UNEVALUATED,
        nested_fields=(),
    )
    assert called is False
    assert spec.default_state is DefaultSemanticState.DEFAULT_FACTORY_UNEVALUATED_BLOCKED


