def test_effect_mutation_does_not_rewrite_lifecycle_dimensions() -> None:
    descriptor = FIRST_PARTY_DESCRIPTORS["recon.fingerprint"]
    before = (
        descriptor.idempotency,
        descriptor.retry_eligibility,
        descriptor.compensation,
        descriptor.timeout,
    )
    changed = replace(descriptor, external_effect=ExternalEffectClass.LOCAL_ANALYSIS)
    after = (
        changed.idempotency,
        changed.retry_eligibility,
        changed.compensation,
        changed.timeout,
    )
    assert after == before


