def _dry_run_source(descriptor: ModuleDescriptor) -> str:
    relative = Path(*descriptor.dry_run.owner_module.split(".")).with_suffix(".py")
    return (_repository_root() / relative).read_text(encoding="utf-8")


def _mutated_dry_run_source(descriptor: ModuleDescriptor, mutation: str) -> str:
    tree = ast.parse(_dry_run_source(descriptor))
    owner = next(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == descriptor.dry_run.owner_class
    )
    method = next(
        node
        for node in owner.body
        if isinstance(node, ast.AsyncFunctionDef) and node.name == descriptor.dry_run.method_name
    )
    guard_index = next(
        index
        for index, node in enumerate(method.body)
        if isinstance(node, ast.If) and "dry_run" in ast.unparse(node.test)
    )
    guard = method.body[guard_index]
    assert isinstance(guard, ast.If)
    if mutation == "remove_guard":
        method.body.pop(guard_index)
    elif mutation == "invert_guard":
        guard.test = ast.UnaryOp(op=ast.Not(), operand=guard.test)
    elif mutation == "poison_guard":
        guard.test = ast.Call(
            func=ast.Name(id="getattr", ctx=ast.Load()),
            args=(
                ast.Name(id="ctx", ctx=ast.Load()),
                ast.Constant(value="dry_run_poisoned"),
                ast.Constant(value=False),
            ),
            keywords=(),
        )
    elif mutation == "replace_return_with_fallthrough":
        guard.body[-1] = ast.Pass()
    elif mutation == "insert_effect_before_guard":
        method.body.insert(
            guard_index,
            ast.Expr(
                value=ast.Call(
                    func=ast.Name(id="external_effect_canary", ctx=ast.Load()),
                    args=(),
                    keywords=(),
                )
            ),
        )
    else:
        raise AssertionError("ARES-5C1-DRY-RUN-MUTATION")
    return ast.unparse(ast.fix_missing_locations(tree))


@pytest.mark.parametrize("module_id", DRY_RUN_MODULE_IDS, ids=DRY_RUN_MODULE_IDS)
def test_each_dry_run_provenance_matches_actual_source(module_id: str) -> None:
    descriptor = FIRST_PARTY_DESCRIPTORS[module_id]
    assert validate_dry_run_source(descriptor, _dry_run_source(descriptor)) is descriptor.dry_run


@pytest.mark.parametrize("module_id", DRY_RUN_MODULE_IDS, ids=DRY_RUN_MODULE_IDS)
@pytest.mark.parametrize(
    "mutation",
    DRY_RUN_SOURCE_MUTATIONS,
    ids=DRY_RUN_SOURCE_MUTATIONS,
)
def test_each_dry_run_source_mutation_is_detected(
    module_id: str,
    mutation: str,
) -> None:
    descriptor = FIRST_PARTY_DESCRIPTORS[module_id]
    with pytest.raises(DescriptorReadinessError) as captured:
        validate_dry_run_source(
            descriptor,
            _mutated_dry_run_source(descriptor, mutation),
        )
    assert captured.value.code is ReadinessCode.DRY_RUN_PROVENANCE_MISMATCH


@pytest.mark.parametrize("module_id", DRY_RUN_MODULE_IDS, ids=DRY_RUN_MODULE_IDS)
def test_each_declared_dry_run_provenance_mutation_is_detected(module_id: str) -> None:
    descriptor = FIRST_PARTY_DESCRIPTORS[module_id]
    changed_contract = replace(
        descriptor.dry_run,
        provenance_digest="0" * 64,
    )
    changed = replace(descriptor, dry_run=changed_contract)
    assert changed.semantic_digest != descriptor.semantic_digest
    with pytest.raises(DescriptorReadinessError) as captured:
        validate_dry_run_source(changed, _dry_run_source(descriptor))
    assert captured.value.code is ReadinessCode.DRY_RUN_PROVENANCE_MISMATCH


def _registry_with_dry_run_flag_poisoned(module_id: str):
    classes = []
    sources = {}
    for descriptor in FIRST_PARTY_DESCRIPTORS.values():
        namespace = {
            "__module__": descriptor.source_module,
            "MODULE_ID": descriptor.module_id,
            "MODULE_CATEGORY": descriptor.category.value,
            "OPSEC_LEVEL": descriptor.opsec.value,
            "OUTPUTS": descriptor.declared_outputs,
            "REQUIRES": descriptor.legacy_requires,
            "CAPABILITIES": descriptor.legacy_capabilities,
            "DRY_RUN_SUPPORTED": descriptor.module_id != module_id,
            "MODULE_TIMEOUT_SECONDS": descriptor.legacy_timeout_override,
        }
        classes.append(type(descriptor.source_class, (), namespace))
        sources[descriptor.module_id] = "builtin"
    return SimpleNamespace(all=lambda: classes, _sources=sources)


@pytest.mark.parametrize("module_id", DRY_RUN_MODULE_IDS, ids=DRY_RUN_MODULE_IDS)
def test_each_inherited_dry_run_flag_poison_invalidates_readiness(module_id: str) -> None:
    with pytest.raises(DescriptorReadinessError) as captured:
        bind_first_party_registry(_registry_with_dry_run_flag_poisoned(module_id))
    assert captured.value.code is ReadinessCode.REGISTRY_BINDING_MISMATCH


@pytest.mark.parametrize("module_id", DRY_RUN_MODULE_IDS, ids=DRY_RUN_MODULE_IDS)
def test_engine_default_poison_does_not_change_descriptor_truth(
    module_id: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from ares.modules.base import BaseModule

    descriptor = FIRST_PARTY_DESCRIPTORS[module_id]
    before = descriptor.semantic_digest
    monkeypatch.setattr(BaseModule, "DRY_RUN_SUPPORTED", False)
    assert validate_dry_run_source(descriptor, _dry_run_source(descriptor)) is descriptor.dry_run
    assert descriptor.semantic_digest == before


def test_dry_run_collection_and_shared_adapter_bindings_are_exact() -> None:
    assert len(DRY_RUN_MODULE_IDS) == 62
    assert len(set(DRY_RUN_MODULE_IDS)) == 62
    assert set(DRY_RUN_MODULE_IDS) == set(EXPECTED_RECORDS)
    assert {
        module_id
        for module_id in DRY_RUN_MODULE_IDS
        if FIRST_PARTY_DESCRIPTORS[module_id].dry_run.state is DryRunState.SHARED_ADAPTER_PROVEN
    } == SHARED_DRY_RUN_IDS
    expected_nodes = len(DRY_RUN_MODULE_IDS) * (len(DRY_RUN_SOURCE_MUTATIONS) + 4)
    assert expected_nodes == 558


def test_builtin_registry_binding_never_constructs_or_executes(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from ares.core.plugin.loader import PluginLoader
    from ares.modules.base import BaseModule

    def tripwire(*_args, **_kwargs):
        raise AssertionError("ARES-5C1-TRIPWIRE")

    async def async_tripwire(*_args, **_kwargs):
        raise AssertionError("ARES-5C1-TRIPWIRE")

    monkeypatch.setattr(BaseModule, "__init__", tripwire)
    monkeypatch.setattr(BaseModule, "validate", async_tripwire)
    monkeypatch.setattr(BaseModule, "execute", async_tripwire)
    monkeypatch.setattr(BaseModule, "run", async_tripwire)

    loader = PluginLoader()
    loaded = loader._load_builtin()
    bound = bind_first_party_registry(loader.registry)
    assert loaded == 62
    assert len(bound) == 62
    assert not loader.errors


def test_strict_parser_rejects_unknown_and_preserves_canonical_coercion() -> None:
    raw = {"target": "safe.example", "timeout": "4.5"}
    original = deepcopy(raw)
    result = canonicalize_parameters("recon.fingerprint", raw)
    assert raw == original
    assert result.values["target"] == "safe.example"
    assert result.values["timeout"] == 4.5
    assert "safe.example" not in repr(result)

    with pytest.raises(DescriptorReadinessError) as captured:
        canonicalize_parameters(
            "recon.fingerprint",
            {"target": "safe.example", "unknown_field": "sensitive-canary"},
        )
    assert captured.value.code is ReadinessCode.PARAMETERS_UNKNOWN_FIELD
    assert "sensitive-canary" not in str(captured.value)


def test_strict_parser_rejects_non_mapping_and_sanitizes_model_failure() -> None:
    with pytest.raises(DescriptorReadinessError) as non_mapping:
        canonicalize_parameters("recon.fingerprint", ["not", "a", "mapping"])  # type: ignore[arg-type]
    assert non_mapping.value.code is ReadinessCode.PARAMETERS_NOT_MAPPING

    with pytest.raises(DescriptorReadinessError) as invalid:
        canonicalize_parameters("recon.fingerprint", {"target": "x"})
    assert invalid.value.code is ReadinessCode.PARAMETERS_INVALID
    assert "x" not in str(invalid.value)


