def test_destination_extraction_covers_scalar_list_optional_and_secondary_kinds() -> None:
    relay = extract_destinations(
        "lateral.ntlm_relay",
        {
            "dc": "dc.safe.example",
            "domain": "safe.example",
            "targets": ["one.safe.example", "one.safe.example", "two.safe.example"],
            "coerce_source": "source.safe.example",
        },
    )
    assert [item.kind for item in relay].count(DestinationKind.RELAY_TARGET) == 2
    assert relay[0].kind is DestinationKind.HOST
    assert all("safe.example" not in repr(item) for item in relay)

    callback = extract_destinations(
        "ad.coerce",
        {
            "dc": "dc.safe.example",
            "domain": "safe.example",
            "listener_ip": "listener.safe.example",
        },
    )
    assert any(item.kind is DestinationKind.CALLBACK for item in callback)

    cloud = extract_destinations(
        "cloud.azure",
        {"subscription_id": "subscription", "tenant_id": "tenant"},
    )
    assert {item.kind for item in cloud} == {
        DestinationKind.CLOUD_SUBSCRIPTION,
        DestinationKind.CLOUD_TENANT,
    }

    files = extract_destinations(
        "credential.crack",
        {"hashcat_path": "tool", "wordlist": "words", "rules": "rules"},
    )
    assert len(files) == 3
    assert all(item.kind is DestinationKind.LOCAL_FILE for item in files)

    exfil = extract_destinations(
        "exfil.staged_collection",
        {"target": "host", "destination": "collection"},
    )
    assert any(item.kind is DestinationKind.EXFILTRATION_PATH for item in exfil)


