def _independent_parameter_projection(spec: ParameterFieldSpec) -> dict[str, object]:
    return {
        "name": spec.name,
        "canonical_type": spec.canonical_type.value,
        "required": spec.required,
        "default_state": spec.default_state.value,
        "public_default_digest": spec.public_default_digest,
        "legacy_schema_secret": spec.legacy_schema_secret,
        "sensitivity": spec.sensitivity.value,
        "blocker_code": spec.blocker_code.value if spec.blocker_code is not None else None,
        "nested_fields": tuple(
            _independent_parameter_projection(item) for item in spec.nested_fields
        ),
    }


def _independent_descriptor_projection(descriptor: ModuleDescriptor) -> dict[str, object]:
    return {
        "contract_version": descriptor.contract_version,
        "module_id": descriptor.module_id,
        "category": descriptor.category.value,
        "source_module": descriptor.source_module,
        "source_class": descriptor.source_class,
        "parameter_model_identity": descriptor.parameter_model_identity,
        "parameter_fields": tuple(
            _independent_parameter_projection(item) for item in descriptor.parameter_fields
        ),
        "parameter_schema_digest": descriptor.parameter_schema_digest,
        "declared_outputs": descriptor.declared_outputs,
        "opsec": descriptor.opsec.value,
        "minimum_role": descriptor.minimum_role.value,
        "explicit_attempt_approval": descriptor.explicit_attempt_approval,
        "required_capabilities": tuple(
            sorted(item.value for item in descriptor.required_capabilities)
        ),
        "capability_match": descriptor.capability_match.value,
        "destination_state": descriptor.destination_state.value,
        "destinations": tuple(
            {
                "kind": item.kind.value,
                "source_path": item.source_path,
                "cardinality": item.cardinality.value,
                "scope": item.scope.value,
                "state": item.state.value,
            }
            for item in descriptor.destinations
        ),
        "credential_policy": {
            "state": descriptor.credential_policy.state.value,
            "allowed_handle_kinds": tuple(
                sorted(item.value for item in descriptor.credential_policy.allowed_handle_kinds)
            ),
            "ambient_dependencies": tuple(
                sorted(item.value for item in descriptor.credential_policy.ambient_dependencies)
            ),
        },
        "external_effect": descriptor.external_effect.value,
        "idempotency": descriptor.idempotency.value,
        "retry_eligibility": descriptor.retry_eligibility.value,
        "cancellation_ownership": descriptor.cancellation_ownership.value,
        "compensation": descriptor.compensation.value,
        "timeout": {
            "seconds": descriptor.timeout.seconds,
            "source": descriptor.timeout.source.value,
            "settlement": descriptor.timeout.settlement.value,
        },
        "dry_run": {
            "state": descriptor.dry_run.state.value,
            "owner_module": descriptor.dry_run.owner_module,
            "owner_class": descriptor.dry_run.owner_class,
            "method_name": descriptor.dry_run.method_name,
            "guard_semantics": descriptor.dry_run.guard_semantics.value,
            "termination": descriptor.dry_run.termination.value,
            "provenance_digest": descriptor.dry_run.provenance_digest,
        },
        "result_contract": {
            "findings": descriptor.result_contract.findings.value,
            "credentials": descriptor.result_contract.credentials.value,
            "discovered_hosts": descriptor.result_contract.discovered_hosts.value,
            "loot_artifacts": descriptor.result_contract.loot_artifacts.value,
            "authoritative_evidence": descriptor.result_contract.authoritative_evidence.value,
        },
        "descriptor_complete": descriptor.descriptor_complete,
        "future_gateway_eligible": descriptor.future_gateway_eligible,
        "blocker_codes": tuple(sorted(item.value for item in descriptor.blocker_codes)),
        "legacy_requires": descriptor.legacy_requires,
        "legacy_capabilities": tuple(
            sorted(item.value for item in descriptor.legacy_capabilities)
        ),
        "legacy_dry_run_supported": descriptor.legacy_dry_run_supported,
        "legacy_timeout_override": descriptor.legacy_timeout_override,
    }


def _projection_differences(
    before: object,
    after: object,
    path: tuple[object, ...] = (),
) -> set[tuple[object, ...]]:
    if isinstance(before, dict) and isinstance(after, dict):
        differences: set[tuple[object, ...]] = set()
        for key in set(before) | set(after):
            if key not in before or key not in after:
                differences.add((*path, key))
            else:
                differences.update(
                    _projection_differences(before[key], after[key], (*path, key))
                )
        return differences
    if isinstance(before, tuple) and isinstance(after, tuple):
        if len(before) != len(after):
            return {path}
        differences = set()
        for index, (left, right) in enumerate(zip(before, after, strict=True)):
            differences.update(_projection_differences(left, right, (*path, index)))
        return differences
    return set() if before == after else {path}


def _field_tuple(
    descriptor: ModuleDescriptor,
    field_name: str,
    replacement: ParameterFieldSpec,
) -> tuple[ParameterFieldSpec, ...]:
    return tuple(
        replacement if item.name == field_name else item
        for item in descriptor.parameter_fields
    )


def _fresh_eligible_descriptor() -> ModuleDescriptor:
    source = _construct_descriptor(FIRST_PARTY_DESCRIPTORS["recon.fingerprint"])
    result = ResultContract(
        findings=ContractState.PROVEN_NONE,
        credentials=ContractState.PROVEN_NONE,
        discovered_hosts=ContractState.PROVEN_NONE,
        loot_artifacts=ContractState.PROVEN_NONE,
        authoritative_evidence=ContractState.SUPPORTED,
    )
    return _construct_descriptor(
        source,
        idempotency=IdempotencyClass.PROVEN_IDEMPOTENT,
        retry_eligibility=RetryEligibility.NEVER,
        cancellation_ownership=CancellationOwnership.OWNED,
        compensation=CompensationClass.NOT_APPLICABLE,
        timeout=TimeoutPolicy(
            source.timeout.seconds,
            source.timeout.source,
            TimeoutSettlement.PROVEN,
        ),
        result_contract=result,
        blocker_codes=(),
        future_gateway_eligible=True,
    )


def _valid_descriptor_pair(
    dimension: str,
) -> tuple[ModuleDescriptor, ModuleDescriptor, tuple[tuple[object, ...], ...]]:
    before = _construct_descriptor(FIRST_PARTY_DESCRIPTORS["ad.adcs"])
    allowed: tuple[tuple[object, ...], ...] = ((dimension,),)
    if dimension == "module_id":
        after = _construct_descriptor(before, module_id="ad.adcs_variant")
    elif dimension == "parameter_model_binding":
        replacement_model = type(
            "ADCSParamsVariant",
            (before.parameter_model,),
            {
                "__module__": "ares.modules.params",
                "__qualname__": "ADCSParamsVariant",
            },
        )
        after = _construct_descriptor(
            before,
            parameter_model=replacement_model,
            parameter_model_identity="ares.modules.params.ADCSParamsVariant",
        )
        allowed = (("parameter_model_identity",),)
    elif dimension == "output_binding":
        after = _construct_descriptor(
            before,
            declared_outputs=(*before.declared_outputs, "descriptor_test_output"),
        )
        allowed = (("declared_outputs",),)
    elif dimension == "noise":
        after = _construct_descriptor(before, opsec=OpsecClassification.MEDIUM)
        allowed = (("opsec",),)
    elif dimension == "minimum_role":
        after = _construct_descriptor(before, minimum_role=MinimumRole.TEAM_LEAD)
    elif dimension == "attempt_approval":
        after = _construct_descriptor(before, explicit_attempt_approval=True)
        allowed = (("explicit_attempt_approval",),)
    elif dimension == "capability_set":
        after = _construct_descriptor(
            before,
            required_capabilities=(*before.required_capabilities, Capability.CAP_FS),
        )
        allowed = (("required_capabilities",),)
    elif dimension == "parameter_schema_identity":
        after = _construct_descriptor(before, parameter_fields=tuple(reversed(before.parameter_fields)))
        allowed = (("parameter_fields",), ("parameter_schema_digest",))
    elif dimension in {
        "parameter_name",
        "parameter_type",
        "requiredness",
        "public_default_state",
        "public_default_value",
        "secret_default_state",
        "sensitivity",
    }:
        field_name = "use_ldaps" if dimension.startswith("public_default") else "username"
        if dimension == "secret_default_state":
            field_name = "target_user"
        original = next(item for item in before.parameter_fields if item.name == field_name)
        field_changes = {
            "parameter_name": {"name": "operator_name"},
            "parameter_type": {"canonical_type": ParameterType.OPTIONAL_STRING},
            "requiredness": {
                "required": False,
                "default_state": DefaultSemanticState.DEFAULT_NONE,
            },
            "public_default_state": {
                "default_state": DefaultSemanticState.DEFAULT_NONE,
                "public_default_digest": None,
            },
            "public_default_value": {"public_default_digest": "1" * 64},
            "secret_default_state": {
                "default_state": DefaultSemanticState.DEFAULT_EMPTY,
                "blocker_code": None,
            },
            "sensitivity": {"sensitivity": Sensitivity.SECRET},
        }[dimension]
        replacement = _copy_parameter_field(original, **field_changes)
        after = _construct_descriptor(
            before,
            parameter_fields=_field_tuple(before, field_name, replacement),
        )
        allowed = (("parameter_fields",), ("parameter_schema_digest",))
    elif dimension == "destination_state":
        after = _construct_descriptor(before, destination_state=ContractState.BLOCKED_BY_POLICY)
    elif dimension in {
        "destination_kind",
        "destination_path",
        "destination_cardinality",
        "destination_scope",
    }:
        original = before.destinations[-1]
        destination_changes = {
            "destination_kind": {"kind": DestinationKind.SERVICE_PRINCIPAL},
            "destination_path": {"source_path": "username"},
            "destination_cardinality": {"cardinality": DestinationCardinality.COLLECTION},
            "destination_scope": {"scope": ScopeSemantics.PROVIDER_BOUNDARY},
        }[dimension]
        replacement = replace(original, **destination_changes)
        after = _construct_descriptor(
            before,
            destinations=(*before.destinations[:-1], replacement),
        )
        allowed = (("destinations",),)
    elif dimension == "credential_state":
        before = _construct_descriptor(FIRST_PARTY_DESCRIPTORS["recon.fingerprint"])
        after = _construct_descriptor(
            before,
            credential_policy=CredentialSourcePolicy(
                ContractState.PROVEN_NONE,
                before.credential_policy.allowed_handle_kinds,
                before.credential_policy.ambient_dependencies,
            ),
        )
        allowed = (("credential_policy",),)
    elif dimension == "allowed_handle_kind":
        after = _construct_descriptor(
            before,
            credential_policy=CredentialSourcePolicy(
                before.credential_policy.state,
                (*before.credential_policy.allowed_handle_kinds, OpaqueCredentialKind.API_TOKEN),
                before.credential_policy.ambient_dependencies,
            ),
        )
        allowed = (("credential_policy",),)
    elif dimension == "ambient_dependency":
        after = _construct_descriptor(
            before,
            credential_policy=CredentialSourcePolicy(
                before.credential_policy.state,
                before.credential_policy.allowed_handle_kinds,
                (
                    *before.credential_policy.ambient_dependencies,
                    AmbientCredentialDependency.ENV_OPENAI_API_KEY,
                ),
            ),
        )
        allowed = (("credential_policy",),)
    elif dimension in {"effect", "idempotency", "retry", "cancellation", "compensation"}:
        before = _construct_descriptor(FIRST_PARTY_DESCRIPTORS["recon.fingerprint"])
        lifecycle_changes = {
            "effect": {"external_effect": ExternalEffectClass.LOCAL_ANALYSIS},
            "idempotency": {"idempotency": IdempotencyClass.CONDITIONAL},
            "retry": {"retry_eligibility": RetryEligibility.NEVER},
            "cancellation": {"cancellation_ownership": CancellationOwnership.NOT_APPLICABLE},
            "compensation": {"compensation": CompensationClass.UNSUPPORTED},
        }[dimension]
        after = _construct_descriptor(before, **lifecycle_changes)
        allowed = (
            (
                {
                    "effect": "external_effect",
                    "retry": "retry_eligibility",
                    "cancellation": "cancellation_ownership",
                }.get(dimension, dimension),
            ),
        )
    elif dimension == "timeout":
        after = _construct_descriptor(
            before,
            timeout=TimeoutPolicy(
                before.timeout.seconds + 1,
                before.timeout.source,
                before.timeout.settlement,
            ),
        )
    elif dimension in {"dry_run_state", "dry_run_provenance"}:
        dry_changes = (
            {"state": DryRunState.SHARED_ADAPTER_PROVEN}
            if dimension == "dry_run_state"
            else {"provenance_digest": "2" * 64}
        )
        after = _construct_descriptor(before, dry_run=replace(before.dry_run, **dry_changes))
        allowed = (("dry_run",),)
    elif dimension in {
        "findings_authority",
        "credential_output_authority",
        "host_output_authority",
        "artifact_authority",
        "evidence_authority",
    }:
        result_changes = {
            "findings_authority": {"findings": ContractState.PROVEN_NONE},
            "credential_output_authority": {"credentials": ContractState.PROVEN_NONE},
            "host_output_authority": {"discovered_hosts": ContractState.PROVEN_NONE},
            "artifact_authority": {"loot_artifacts": ContractState.PROVEN_NONE},
            "evidence_authority": {"authoritative_evidence": ContractState.PROVEN_NONE},
        }[dimension]
        after = _construct_descriptor(
            before,
            result_contract=replace(before.result_contract, **result_changes),
        )
        allowed = (("result_contract",),)
    elif dimension == "eligibility":
        before = _fresh_eligible_descriptor()
        after = _construct_descriptor(before, future_gateway_eligible=False)
        allowed = (("future_gateway_eligible",),)
    elif dimension == "blocker_set":
        before = _construct_descriptor(FIRST_PARTY_DESCRIPTORS["recon.fingerprint"])
        after = _construct_descriptor(
            before,
            blocker_codes=(*before.blocker_codes, BlockerCode.DEFAULT_FACTORY_UNEVALUATED),
        )
        allowed = (("blocker_codes",),)
    else:
        raise AssertionError("ARES-5C1-UNMAPPED-DIGEST-DIMENSION")
    return before, after, allowed


def _path_is_allowed(
    path: tuple[object, ...],
    allowed: tuple[tuple[object, ...], ...],
) -> bool:
    return any(path[: len(prefix)] == prefix for prefix in allowed)


@pytest.mark.parametrize(
    "dimension",
    VALID_PAIR_DIMENSIONS,
    ids=[f"valid-pair::{dimension}" for dimension in VALID_PAIR_DIMENSIONS],
)
def test_digest_valid_pair(dimension: str) -> None:
    before, after, allowed = _valid_descriptor_pair(dimension)
    before_projection = _independent_descriptor_projection(before)
    after_projection = _independent_descriptor_projection(after)
    differences = _projection_differences(before_projection, after_projection)
    reduced = (
        bool(differences),
        all(_path_is_allowed(path, allowed) for path in differences),
        descriptor_semantic_digest(before) != descriptor_semantic_digest(after),
    )
    assert reduced == (True, True, True)


INVARIANT_INVALID_ALTERNATIVES = (
    ("contract_version", "different-version"),
    ("contract_version", "wrong-type"),
    ("capability_match_semantics", "unsupported-enum"),
    ("capability_match_semantics", "wrong-type"),
    ("category", "mismatched-enum"),
    ("category", "wrong-type"),
    ("completeness", "false"),
    ("completeness", "truthy-non-boolean"),
)


@pytest.mark.parametrize(
    ("dimension", "alternative"),
    INVARIANT_INVALID_ALTERNATIVES,
    ids=[
        f"invariant-rejection::{dimension}::{alternative}"
        for dimension, alternative in INVARIANT_INVALID_ALTERNATIVES
    ],
)
def test_invariant_rejection(dimension: str, alternative: str) -> None:
    before = _construct_descriptor(FIRST_PARTY_DESCRIPTORS["recon.fingerprint"])

    class UnsupportedCapabilityMatch(str, Enum):
        ANY_REQUIRED = "any_required"

    mutations = {
        ("contract_version", "different-version"): {
            "contract_version": "ares.module-descriptor.invalid"
        },
        ("contract_version", "wrong-type"): {"contract_version": 2},
        ("capability_match_semantics", "unsupported-enum"): {
            "capability_match": UnsupportedCapabilityMatch.ANY_REQUIRED
        },
        ("capability_match_semantics", "wrong-type"): {
            "capability_match": "all_required"
        },
        ("category", "mismatched-enum"): {"category": ModuleCategory.NETWORK},
        ("category", "wrong-type"): {"category": "recon"},
        ("completeness", "false"): {"descriptor_complete": False},
        ("completeness", "truthy-non-boolean"): {"descriptor_complete": 1},
    }
    with pytest.raises(DescriptorReadinessError) as captured:
        _construct_descriptor(before, **mutations[(dimension, alternative)])
    assert captured.value.code is ReadinessCode.INVALID_DESCRIPTOR


INVARIANT_PROJECTION_FIELDS = {
    "contract_version": ("contract_version", CONTRACT_VERSION),
    "capability_match_semantics": ("capability_match", "all_required"),
    "category": ("category", "recon"),
    "completeness": ("descriptor_complete", True),
}


@pytest.mark.parametrize(
    "dimension",
    INVARIANT_DIMENSIONS,
    ids=[f"invariant-projection::{dimension}" for dimension in INVARIANT_DIMENSIONS],
)
def test_invariant_projection(
    dimension: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    descriptor = _construct_descriptor(FIRST_PARTY_DESCRIPTORS["recon.fingerprint"])
    field_name, expected_value = INVARIANT_PROJECTION_FIELDS[dimension]
    independent = _independent_descriptor_projection(descriptor)
    original_projection = descriptor_module._semantic_data
    complete_projection = original_projection(descriptor)
    normal_digest = descriptor_semantic_digest(descriptor)

    def omit_invariant(value: ModuleDescriptor) -> dict[str, object]:
        projected = original_projection(value)
        projected.pop(field_name)
        return projected

    monkeypatch.setattr(descriptor_module, "_semantic_data", omit_invariant)
    omitted_projection = omit_invariant(descriptor)
    omitted_digest = descriptor_semantic_digest(descriptor)
    reduced = (
        independent[field_name] == expected_value,
        complete_projection[field_name] == expected_value,
        field_name not in omitted_projection,
        set(complete_projection) - set(omitted_projection) == {field_name},
        all(
            complete_projection[key] == omitted_projection[key]
            for key in omitted_projection
        ),
        omitted_digest != normal_digest,
    )
    assert reduced == (True, True, True, True, True, True)


def test_semantic_projection_omission_tripwire_detects_missing_real_field(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    before = _construct_descriptor(FIRST_PARTY_DESCRIPTORS["recon.fingerprint"])
    after = _construct_descriptor(before, explicit_attempt_approval=True)
    independent_changes = _projection_differences(
        _independent_descriptor_projection(before),
        _independent_descriptor_projection(after),
    )
    normal_changed = descriptor_semantic_digest(before) != descriptor_semantic_digest(after)
    original_projection = descriptor_module._semantic_data

    def omit_approval(value: ModuleDescriptor) -> dict[str, object]:
        projected = original_projection(value)
        projected.pop("explicit_attempt_approval")
        return projected

    monkeypatch.setattr(descriptor_module, "_semantic_data", omit_approval)
    omitted_equal = descriptor_semantic_digest(before) == descriptor_semantic_digest(after)
    reduced = (
        independent_changes == {("explicit_attempt_approval",)},
        normal_changed,
        omitted_equal,
    )
    assert reduced == (True, True, True)


def test_digest_mutation_matrix_uses_real_descriptor_path() -> None:
    source = Path(__file__).read_text(encoding="utf-8")
    tree = ast.parse(source)
    functions = {
        node.name: node
        for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }
    guarded = {
        "_independent_descriptor_projection",
        "_valid_descriptor_pair",
        "test_digest_valid_pair",
    }
    guarded_calls = {
        node.func.id
        for name in guarded
        for node in ast.walk(functions[name])
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
    }
    reduced = (
        "_sha256_json" not in guarded_calls,
        "_semantic_data" not in guarded_calls,
        "_mutate_semantic_payload" not in functions,
        "descriptor_semantic_digest" in guarded_calls,
        "_independent_descriptor_projection" in guarded_calls,
    )
    assert reduced == (True, True, True, True, True)


