    assert set(VALID_PAIR_DIMENSIONS) | set(INVARIANT_DIMENSIONS) == set(DIGEST_DIMENSIONS)
    assert not (set(VALID_PAIR_DIMENSIONS) & set(INVARIANT_DIMENSIONS))


