def test_registry_rejects_partial_external_and_replacement_metadata() -> None:
    descriptor = FIRST_PARTY_DESCRIPTORS["recon.fingerprint"]

    class PartialRegistry:
        _sources = {descriptor.module_id: "builtin"}

        @staticmethod
        def all():
            return [SimpleNamespace(MODULE_ID=descriptor.module_id)]

    with pytest.raises(DescriptorReadinessError) as partial:
        bind_first_party_registry(PartialRegistry())
    assert partial.value.code is ReadinessCode.REGISTRY_SET_MISMATCH

    class ExternalRegistry:
        _sources = {descriptor.module_id: "external:catalog"}

        @staticmethod
        def all():
            return [SimpleNamespace(MODULE_ID=descriptor.module_id)]

    with pytest.raises(DescriptorReadinessError) as external:
        bind_first_party_registry(ExternalRegistry())
    assert external.value.code is ReadinessCode.UNTRUSTED_EXTERNAL_METADATA


def test_external_plugin_lookup_never_imports_request_selected_module(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    marker = tmp_path / "side_effect_marker"
    plugin = tmp_path / "external_canary.py"
    plugin.write_text(
        "from pathlib import Path\n"
        f"Path({str(marker)!r}).write_text('unexpected', encoding='utf-8')\n",
        encoding="utf-8",
    )
    monkeypatch.syspath_prepend(str(tmp_path))
    assert get_descriptor("external.canary") is None
    with pytest.raises(DescriptorReadinessError) as missing:
        require_descriptor("external.canary")
    assert missing.value.code is ReadinessCode.DESCRIPTOR_NOT_FOUND
    assert not marker.exists()
    assert "external_canary" not in sys.modules


@pytest.mark.parametrize("ordering", ["normal", "reverse", "permuted"])
def test_registration_order_does_not_change_digest(ordering: str) -> None:
    module_ids = list(EXPECTED_RECORDS)
    if ordering == "reverse":
        module_ids.reverse()
    elif ordering == "permuted":
        module_ids = module_ids[::2] + module_ids[1::2]
    pairs = sorted(
        (
            module_id,
            FIRST_PARTY_DESCRIPTORS[module_id].semantic_digest,
        )
        for module_id in module_ids
    )
    aggregate = hashlib.sha256(json.dumps(pairs, separators=(",", ":")).encode("ascii")).hexdigest()
    expected_pairs = sorted(
        (module_id, expected["semantic_digest"]) for module_id, expected in EXPECTED_RECORDS.items()
    )
    expected_aggregate = hashlib.sha256(
        json.dumps(expected_pairs, separators=(",", ":")).encode("ascii")
    ).hexdigest()
    assert aggregate == expected_aggregate


