def test_mapping_order_cwd_environment_and_process_are_nonsemantic(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    descriptor = FIRST_PARTY_DESCRIPTORS["recon.fingerprint"]
    before = descriptor.semantic_digest
    reordered = _construct_descriptor(
        descriptor,
        required_capabilities=tuple(reversed(descriptor.required_capabilities)),
        blocker_codes=tuple(reversed(descriptor.blocker_codes)),
    )
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("ARES_5C1_NONSEMANTIC_CANARY", "fixed")
    assert descriptor_semantic_digest(reordered) == before
    assert descriptor_semantic_digest(descriptor) == before
    serialized = json.dumps(_independent_descriptor_projection(descriptor), sort_keys=True)
    assert str(_repository_root()) not in serialized
    assert str(os.getpid()) not in serialized
    assert "ARES_5C1_NONSEMANTIC_CANARY" not in serialized


def _subprocess_digest(
    tmp_path: Path,
    hash_seed: str,
    ordering: str,
) -> str:
    root = _repository_root()
    code = (
        "import hashlib,json;"
        "from ares.modules.descriptors import FIRST_PARTY_DESCRIPTORS as D;"
        "ids=list(D);"
        f"ids={'list(reversed(ids))' if ordering == 'reverse' else 'ids'};"
        "pairs=sorted((i,D[i].semantic_digest) for i in ids);"
        "print(hashlib.sha256(json.dumps(pairs,separators=(',',':')).encode('ascii')).hexdigest())"
    )
    env = os.environ.copy()
    env["PYTHONHASHSEED"] = hash_seed
    env["PYTHONDONTWRITEBYTECODE"] = "1"
    env["PYTHONPATH"] = str(root)
    completed = subprocess.run(  # noqa: S603 - fixed interpreter and script
        [sys.executable, "-c", code],
        cwd=tmp_path,
        env=env,
        capture_output=True,
        text=True,
        check=False,
        timeout=30,
    )
    reduced = (completed.returncode == 0, completed.stderr == "")
    assert reduced == (True, True)
    return completed.stdout.strip()


def test_digest_repeats_across_process_hashseed_order_and_unrelated_cwd(
    tmp_path: Path,
) -> None:
    results = {
        _subprocess_digest(tmp_path, "1", "normal"),
        _subprocess_digest(tmp_path, "1", "reverse"),
        _subprocess_digest(tmp_path, "97", "normal"),
        _subprocess_digest(tmp_path, "97", "reverse"),
    }
    assert len(results) == 1


def test_descriptor_import_has_no_observed_side_effects(tmp_path: Path) -> None:
    root = _repository_root()
    code = r"""
import contextlib
import io
import json
import os
import socket
import sqlite3
import subprocess
import sys
import threading

observed = {
    "network": 0,
    "listener": 0,
    "subprocess": 0,
    "thread": 0,
    "database": 0,
    "file_write": 0,
}


def deny_connect(*args, **kwargs):
    observed["network"] += 1
    raise AssertionError("ARES-5C1-SIDE-EFFECT")


def deny_listener(*args, **kwargs):
    observed["listener"] += 1
    raise AssertionError("ARES-5C1-SIDE-EFFECT")


def deny_subprocess(*args, **kwargs):
    observed["subprocess"] += 1
    raise AssertionError("ARES-5C1-SIDE-EFFECT")


def deny_thread(*args, **kwargs):
    observed["thread"] += 1
    raise AssertionError("ARES-5C1-SIDE-EFFECT")


def deny_database(*args, **kwargs):
    observed["database"] += 1
    raise AssertionError("ARES-5C1-SIDE-EFFECT")


def audit(event, args):
    if event == "subprocess.Popen":
        observed["subprocess"] += 1
        raise AssertionError("ARES-5C1-SIDE-EFFECT")
    if event == "open" and len(args) > 1:
        mode = args[1]
        if isinstance(mode, str) and any(flag in mode for flag in "wax+"):
            observed["file_write"] += 1


sys.addaudithook(audit)
socket.socket.connect = deny_connect
socket.socket.connect_ex = deny_connect
socket.socket.bind = deny_listener
socket.socket.listen = deny_listener
threading.Thread.start = deny_thread
sqlite3.connect = deny_database
before = (os.getcwd(), tuple(sys.path), dict(os.environ))
stdout = io.StringIO()
stderr = io.StringIO()
with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
    import ares.modules.descriptors as descriptors
after = (os.getcwd(), tuple(sys.path), dict(os.environ))
result = {
    "count": len(descriptors.FIRST_PARTY_DESCRIPTORS),
    "observed": observed,
    "stdout_empty": stdout.getvalue() == "",
    "stderr_empty": stderr.getvalue() == "",
    "process_state_unchanged": before == after,
}
print(json.dumps(result, sort_keys=True))
"""
    env = os.environ.copy()
    env["PYTHONDONTWRITEBYTECODE"] = "1"
    env["PYTHONHASHSEED"] = "41"
    env["PYTHONPATH"] = str(root)
    completed = subprocess.run(  # noqa: S603 - fixed interpreter and script
        [sys.executable, "-c", code],
        cwd=tmp_path,
        env=env,
        capture_output=True,
        text=True,
        check=False,
        timeout=30,
    )
    reduced = (completed.returncode == 0, completed.stderr == "")
    assert reduced == (True, True)
    result = json.loads(completed.stdout)
    assert result == {
        "count": 62,
        "observed": {
            "database": 0,
            "file_write": 0,
            "listener": 0,
            "network": 0,
            "subprocess": 0,
            "thread": 0,
        },
        "process_state_unchanged": True,
        "stderr_empty": True,
        "stdout_empty": True,
    }


def test_live_execution_sources_do_not_call_audit_parser() -> None:
    root = _repository_root()
    callers = []
    for path in (root / "ares").rglob("*.py"):
        if path.name == "descriptors.py":
            continue
        if "canonicalize_parameters" in path.read_text(encoding="utf-8"):
            callers.append(path)
    assert not callers


def test_category_default_capability_inference_is_not_used(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import ares.core.capabilities as capabilities

    def tripwire(*_args, **_kwargs):
        raise AssertionError("ARES-5C1-CATEGORY-INFERENCE")

    monkeypatch.setattr(
        capabilities,
        "default_capabilities_for_category",
        tripwire,
    )
    assert len(FIRST_PARTY_DESCRIPTORS) == 62
    assert all(
        type(descriptor.required_capabilities) is tuple
        for descriptor in FIRST_PARTY_DESCRIPTORS.values()
    )
